def heap_queue_largest(nums, n):
    largest_elements = []
    for num in nums:
        if len(largest_elements) < n:
            largest_elements.append(num)
        else:
            if num > min(largest_elements):
                largest_elements.remove(min(largest_elements))
                largest_elements.append(num)
    largest_elements.sort(reverse=True)
    return largest_elements

