    def sum_divisors(n):
        sum_ = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                sum_ += i
                if i != n // i:
                    sum_ += n // i
        return sum_

    amicable_sum = 0
    for a in range(2, limit + 1):
        b = sum_divisors(a)
        if a != b and sum_divisors(b) == a:
            amicable_sum += a
    return amicable_sum

