def magic_square_test(matrix):
    n = len(matrix)
    magic_sum = sum(matrix[0])
    for i in range(1, n):
        if sum(matrix[i]) != magic_sum:
            return False
    for j in range(n):
        col_sum = 0
        for i in range(n):
            col_sum += matrix[i][j]
        if col_sum != magic_sum:
            return False
    diag1_sum = 0
    diag2_sum = 0
    for i in range(n):
        diag1_sum += matrix[i][i]
        diag2_sum += matrix[i][n - 1 - i]
    if diag1_sum != magic_sum or diag2_sum != magic_sum:
        return False
    return True

