def pancake_sort(arr):
    n = len(arr)
    for curr_size in range(n, 1, -1):
        mi = arr.index(max(arr[:curr_size]))
        if mi != curr_size - 1:
            if mi != 0:
                arr[:mi+1] = arr[:mi+1][::-1]
            arr[:curr_size] = arr[:curr_size][::-1]
    return arr

