    num = 2
    while count < n:
        if is_newman_prime(num):
            count += 1
        if count == n:
            return num
        num += 1

def is_newman_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True
```

