def max_sum_increasing_subseq(arr, n, i, k):
    dp = [0] * n
    for j in range(n):
        dp[j] = arr[j]
        for l in range(j):
            if arr[j] > arr[l]:
                dp[j] = max(dp[j], dp[l] + arr[j])
    max_sum = 0
    for j in range(i + 1, k + 1):
        max_sum = max(max_sum, dp[j - 1])
    return max_sum

