def get_max_sum(n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    f = {}
    f[1] = 1

    for i in range(2, n + 1):
        f[i] = max( (f[i//2] + f[i//3] + f[i//4] + f[i//5]), i)

    return f[n]

