def find_adverb_position(sentence):
    adverbs = ['clearly', 'slowly', 'quickly', 'carefully', 'easily', 'happily', 'sadly', 'angrily', 'loudly', 'quietly']
    words = sentence.split()
    for i, word in enumerate(words):
        cleaned_word = ''.join(c for c in word if c.isalnum())
        if cleaned_word.lower() in adverbs:
            return (i, sentence.find(cleaned_word), cleaned_word)
    return None

