    if n == 0:
        return 0

    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i

    binom = [0] * (n + 1)
    for i in range(n + 1):
        binom[i] = fact[n] // (fact[i] * fact[n - i])

    sum_prod = 0
    for i in range(n):
        sum_prod += binom[i] * binom[i + 1]

