def get_ludic(n):
    """
    Write a function to get all lucid numbers smaller than or equal to a given integer.
    assert get_ludic(10) == [1, 2, 3, 5, 7]
    """
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    ludic_numbers = []
    for i in range(1, n + 1):
        if is_prime(i):
            ludic_numbers.append(i)
        elif i == 1:
            ludic_numbers.append(i)
        else:
            factors = []
            temp = i
            for j in range(2, int(i**0.5) + 1):
                if temp % j == 0:
                    factors.append(j)
                    while temp % j == 0:
                        temp //= j
            if temp > 1:
                factors.append(temp)

            if len(factors) == 0:
                continue

            is_ludic = True
            for factor in factors:
                if not is_prime(factor):
                    is_ludic = False
                    break

            if is_ludic:
                ludic_numbers.append(i)

    return sorted(list(set(ludic_numbers)))

