def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = {}

    def solve(row, col, total_cost, count):
        if (row, col, total_cost, count) in dp:
            return dp[(row, col, total_cost, count)]

        if row == n - 1 and col == n - 1:
            avg = (total_cost + matrix[row][col]) / (count + 1)
            dp[(row, col, total_cost, count)] = avg
            return avg

        avg = float('-inf')
        if row + 1 < n:
            avg = max(avg, solve(row + 1, col, total_cost + matrix[row][col], count + 1))
        if col + 1 < n:
            avg = max(avg, solve(row, col + 1, total_cost + matrix[row][col], count + 1))

        dp[(row, col, total_cost, count)] = avg
        return avg

    return solve(0, 0, 0, 0)

