    for num in range(startnum, endnum + 1):
        num_str = str(num)
        is_divisible = True
        for digit in num_str:
            digit_int = int(digit)
            if digit_int == 0 or num % digit_int != 0:
                is_divisible = False
                break
        if is_divisible:
            result.append(num)
    return result
```

